import React, { createContext, useContext, useState, useEffect } from 'react';
import { useAuth } from './AuthContext';
import { cartService } from '../services/cartService';

const CartContext = createContext(null);

export const CartProvider = ({ children }) => {
  const [cart, setCart] = useState([]);
  const [loading, setLoading] = useState(false);
  const { isAuthenticated } = useAuth();

  useEffect(() => {
    const load = async () => {
      if (isAuthenticated) {
        setLoading(true);
        try {
          const serverCart = await cartService.getCart();
          setCart(
            (serverCart.items || []).map((item) => ({
              _id: item.product?._id || item.product,
              cartItemId: item._id,
              name: item.product?.name,
              image: item.product?.images?.[0]?.url || '',
              brand: item.product?.brand || '',
              price: item.price,
              qty: item.quantity,
              stock: item.product?.stock || 0
            }))
          );
        } catch (err) {
          setCart([]);
        } finally {
          setLoading(false);
        }
      } else {
        const stored = localStorage.getItem('shopzone_cart');
        setCart(stored ? JSON.parse(stored) : []);
      }
    };
    load();
  }, [isAuthenticated]);

  const saveCart = (items) => {
    setCart(items);
    if (!isAuthenticated) localStorage.setItem('shopzone_cart', JSON.stringify(items));
  };

  const addToCart = async (product, qty = 1) => {
    if (isAuthenticated) {
      const serverCart = await cartService.addToCart({ productId: product._id, quantity: qty });
      saveCart(
        (serverCart.items || []).map((item) => ({
          _id: item.product?._id || item.product,
          cartItemId: item._id,
          name: item.product?.name,
          image: item.product?.images?.[0]?.url || '',
          brand: item.product?.brand || '',
          price: item.price,
          qty: item.quantity,
          stock: item.product?.stock || 0
        }))
      );
      return;
    }

    const existing = cart.find((i) => i._id === product._id);
    if (existing) {
      saveCart(cart.map((i) => (i._id === product._id ? { ...i, qty: i.qty + qty } : i)));
    } else {
      saveCart([...cart, { ...product, qty }]);
    }
  };

  const removeFromCart = async (id) => {
    if (isAuthenticated) {
      const item = cart.find((entry) => entry._id === id);
      if (!item?.cartItemId) return;
      const serverCart = await cartService.removeCartItem(item.cartItemId);
      saveCart(
        (serverCart.items || []).map((cartItem) => ({
          _id: cartItem.product?._id || cartItem.product,
          cartItemId: cartItem._id,
          name: cartItem.product?.name,
          image: cartItem.product?.images?.[0]?.url || '',
          brand: cartItem.product?.brand || '',
          price: cartItem.price,
          qty: cartItem.quantity,
          stock: cartItem.product?.stock || 0
        }))
      );
      return;
    }
    saveCart(cart.filter((i) => i._id !== id));
  };

  const updateQty = async (id, qty) => {
    if (qty < 1) return removeFromCart(id);
    if (isAuthenticated) {
      const item = cart.find((entry) => entry._id === id);
      if (!item?.cartItemId) return;
      const serverCart = await cartService.updateCartItem(item.cartItemId, qty);
      saveCart(
        (serverCart.items || []).map((cartItem) => ({
          _id: cartItem.product?._id || cartItem.product,
          cartItemId: cartItem._id,
          name: cartItem.product?.name,
          image: cartItem.product?.images?.[0]?.url || '',
          brand: cartItem.product?.brand || '',
          price: cartItem.price,
          qty: cartItem.quantity,
          stock: cartItem.product?.stock || 0
        }))
      );
      return;
    }
    saveCart(cart.map((i) => (i._id === id ? { ...i, qty } : i)));
  };

  const clearCart = async () => {
    if (isAuthenticated) {
      await cartService.clearCart();
    }
    saveCart([]);
  };

  const total = cart.reduce((sum, i) => sum + i.price * i.qty, 0);
  const count = cart.reduce((sum, i) => sum + i.qty, 0);

  return (
    <CartContext.Provider value={{ 
      cart, 
      addToCart, 
      removeFromCart, 
      updateQty, 
      clearCart, 
      count,
      total,
      loading
    }}>
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => useContext(CartContext);
